WITH nuevo AS (
  INSERT INTO espacios (codigo, nombre, tipo, capacidad, ubicacion, equipamiento, motivo_estado, origen_estado)
  VALUES ($1, $2, $3, $4, $5, ARRAY(SELECT jsonb_array_elements_text($6::jsonb)), 'Espacio registrado', 'usuario')
  RETURNING *
)
SELECT row_to_json(nuevo) AS data, 'Espacio ' || nuevo.codigo || ' registrado' AS mensaje FROM nuevo;

